2	
3	/**
4	 * 路径标识与请求头的基础校验；避免超长或非法标识直接触发数据库错误。
5	 */
6	public final class RequestTokens {
7	
8	    /** 各业务编号在数据库中的最大长度。 */
9	    public static final int MAX_ID_LENGTH = 64;
10	
11	    private RequestTokens() {
12	    }
13	
14	    /**
