1	package com.example.starter.blind.web;
2	
3	import com.example.starter.blind.Actor;
4	import com.example.starter.blind.ActorContext;
5	import com.example.starter.blind.Role;
6	import com.fasterxml.jackson.databind.ObjectMapper;
7	import jakarta.servlet.FilterChain;
8	import jakarta.servlet.ServletException;
9	import jakarta.servlet.http.HttpServletRequest;
10	import jakarta.servlet.http.HttpServletResponse;
11	import org.springframework.http.MediaType;
12	import org.springframework.stereotype.Component;
13	import org.springframework.web.filter.OncePerRequestFilter;
14	
15	import java.io.IOException;
16	import java.util.Map;
17	
18	/**
19	 * 业务接口鉴权过滤器：本题信任本地测试头 X-Actor-Id / X-Role。
20	 * 仅拦截 /api/** ；头缺失或角色非法直接 401，不进入业务与幂等逻辑。
21	 */
22	@Component
23	public class ActorHeaderFilter extends OncePerRequestFilter {
24	
25	    public static final String HEADER_ACTOR = "X-Actor-Id";
26	    public static final String HEADER_ROLE = "X-Role";
27	
28	    private final ActorContext actorContext;
29	    private final ObjectMapper objectMapper;
30	
31	    public ActorHeaderFilter(ActorContext actorContext, ObjectMapper objectMapper) {
32	        this.actorContext = actorContext;
33	        this.objectMapper = objectMapper;
34	    }
35	
36	    @Override
37	    protected boolean shouldNotFilter(HttpServletRequest request) {
38	        return !request.getRequestURI().startsWith("/api/");
39	    }
40	
41	    @Override
42	    protected void doFilterInternal(HttpServletRequest request,
43	                                    HttpServletResponse response,
44	                                    FilterChain filterChain) throws ServletException, IOException {
45	        try {
46	            String actorId = request.getHeader(HEADER_ACTOR);
47	            String roleHeader = request.getHeader(HEADER_ROLE);
48	            if (actorId == null || actorId.isBlank() || roleHeader == null || roleHeader.isBlank()) {
49	                writeError(response, HttpServletResponse.SC_UNAUTHORIZED, "缺少 X-Actor-Id 或 X-Role 请求头");
50	                return;
51	            }
52	            if (actorId.trim().length() > 64) {
53	                writeError(response, HttpServletResponse.SC_BAD_REQUEST, "X-Actor-Id 长度不能超过 64 个字符");
54	                return;
55	            }
56	            final Role role;
57	            try {
58	                role = Role.valueOf(roleHeader.trim());
59	            } catch (IllegalArgumentException e) {
60	                writeError(response, HttpServletResponse.SC_UNAUTHORIZED, "X-Role 仅允许 COORDINATOR 或 REVIEWER");
61	                return;
62	            }
63	            actorContext.set(new Actor(actorId.trim(), role));
64	            filterChain.doFilter(request, response);
65	        } finally {
66	            actorContext.clear();
67	        }
68	    }
69	
70	    private void writeError(HttpServletResponse response, int status, String message) throws IOException {
71	        response.setStatus(status);
72	        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
73	        response.setCharacterEncoding("UTF-8");
74	        objectMapper.writeValue(response.getWriter(),
75	                Map.of("error", "UNAUTHORIZED", "message", message));
76	    }
77	}
