package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 创建研究中心请求体。
 *
 * @param leadActorId 中心负责人操作者编号；启用申请必须由此人先确认
 */
public record CreateSiteRequest(
        @NotBlank(message = "leadActorId 不能为空")
        @Size(max = 64, message = "leadActorId 最长 64 字符")
        String leadActorId
) {
}

package com.example.starter.blind.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * 中心启用配置版本请求体；每次提交生成一个新版本申请，版本号由服务端递增。
 *
 * @param blocks 区组名额列表，区组号必须从 1 开始连续且不重复
 */
public record SubmitSiteConfigRequest(
        @NotEmpty(message = "blocks 不能为空")
        @Valid
        List<BlockQuotaRequest> blocks
) {

    /**
     * 单个区组的可分配名额（冻结量），非负整数。
     *
     * @param blockNo 区组号，从 1 开始
     * @param quota   该区组可分配名额，0 表示该区组不接受分配
     */
    public record BlockQuotaRequest(
            @NotNull(message = "blockNo 不能为空")
            @Min(value = 1, message = "blockNo 必须从 1 开始")
            @Max(value = 64, message = "区组数量不能超过 64")
            Integer blockNo,

            @NotNull(message = "quota 不能为空")
            @Min(value = 0, message = "quota 不能为负")
            @Max(value = 1_000_000, message = "quota 超出上限")
            Integer quota
) {
    }
}

package com.example.starter.blind.dto;

/**
 * 研究中心视图；不含区组处理映射，任何角色均不可见盲底。
 *
 * @param siteId        中心编号
 * @param leadActorId   中心负责人操作者编号
 * @param status        INACTIVE / ACTIVE
 * @param activeVersion 当前已启用配置版本号；null 表示从未启用
 * @param createdAt     创建时间，Unix 毫秒，UTC
 * @param activatedAt   最近一次启用时间，Unix 毫秒，UTC；null 表示未启用
 */
public record SiteView(
        String siteId,
        String leadActorId,
        String status,
        Integer activeVersion,
        long createdAt,
        Long activatedAt
) {
}

package com.example.starter.blind.dto;

import java.util.List;

/**
 * 分配方视角视图：只暴露当前已启用快照下各区组的剩余额度，
 * 不返回总名额、已分配量、版本确认留痕，更不包含处理代码或席位序号。
 *
 * @param siteId 中心编号
 * @param blocks 各区组剩余额度
 */
public record RemainingQuotaView(
        String siteId,
        List<BlockRemaining> blocks
) {

    /**
     * 单个区组的剩余可分配量。
     *
     * @param blockNo   区组号，从 1 开始
     * @param remaining 剩余可分配量
     */
    public record BlockRemaining(int blockNo, int remaining) {
    }
}

package com.example.starter.blind.dto;

/**
 * 中心分配视图：只含无含义盲码与区组号，严禁包含处理代码 treatment。
 *
 * @param allocationId  中心分配记录编号
 * @param siteId        中心编号
 * @param participantId 合成参与者编号
 * @param blindCode     随机无含义盲码，与区组/处理组无对应规律
 * @param blockNo       分配到的区组号（不含区组内席位序号）
 * @param allocatedAt   分配时间，Unix 毫秒，UTC
 */
public record SiteAllocationView(
        long allocationId,
        String siteId,
        String participantId,
        String blindCode,
        int blockNo,
        long allocatedAt
) {
}

