        }

        // 若交叉后仍停留在 PENDING（极端串行：先到者未见对方确认），后到者的同键重放不重复启用，
        // 此时再补一次第二确认即可；无论如何最终恰好一次启用与一套快照。
        String status = jdbc.queryForObject(
                "SELECT status FROM site_activation_request WHERE id = ?", String.class, v1);
        if ("PENDING".equals(status)) {
            boolean leadConfirmed = jdbc.queryForObject(
                    "SELECT lead_confirmed FROM site_activation_request WHERE id = ?",
